import logging

from taf.ccs.aashell import aashell


class AashellInterface:
    def __init__(self, vm: dict, node_enb_ip: str = "192.168.255.129"):
        self.vm = vm
        self.alias = "aashell"
        self.aashell: aashell = None
        self.node_enb_ip = node_enb_ip

    def __enter__(self):
        if isinstance(self.vm, dict) and 'bts_host_ip' in self.vm:
            del self.vm['bts_host_ip']
        self.aashell = aashell()
        self.aashell.create_aashell_cli(name=self.alias, hops=dict(host=self.node_enb_ip, proxy=self.vm))
        self.aashell.setup(alias=self.alias)
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.aashell:
            logging.debug(f"Closing connecting for {self.alias}")
            self.aashell.teardown(self.alias)

    def set_flags(self, flags: list):
        if isinstance(flags, str):
            flags = [flags]
        for flag in flags:
            flag_splitted = flag.split("=")
            self.aashell.change_rad_param(self.alias, flag_splitted[0], flag_splitted[1])

    def teardown(self):
        self.aashell.teardown(self.alias)
